-- Execute inside BEGIN ... ROLLBACK only; the live activation switch is restored by rollback.
create temporary table bingo_qa_results(test text);
create function pg_temp.check_bingo(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; insert into bingo_qa_results values(label); end; $$;
create or replace function private.bingo_enabled() returns boolean language sql immutable set search_path='' as $$select false;$$;
select pg_temp.check_bingo(not private.bingo_enabled(),'Disabled switch blocks competition');
create temporary table baseline_sandbox as select md5(coalesce(jsonb_agg(to_jsonb(s) order by to_jsonb(s)::text)::text,'')) checksum from public.bingo_test_sessions s;
insert into auth.users(id) values('11111111-2222-4333-8444-555555555555'),('11111111-2222-4333-8444-555555555556');
insert into public.profiles(id,email,display_name,auto_elimination_recheck_after) values('11111111-2222-4333-8444-555555555555','bingo-fixture-one@example.invalid','Bingo fixture one','2026-10-04'),('11111111-2222-4333-8444-555555555556','bingo-fixture-two@example.invalid','Bingo fixture two','2026-10-04');
select pg_temp.check_bingo((select count(*)=2 from public.bingo_results where user_id::text like '11111111-2222-4333-8444-55555555555%'),'Empty participant boards created, not copied from sandbox');
select set_config('request.jwt.claims','{"sub":"11111111-2222-4333-8444-555555555555","role":"authenticated"}',true);
do $$ begin begin perform private.bingo_mutation('complete','2026-10-05',0,'2026-10-05T12:00:00+02'); raise exception 'Disabled write accepted'; exception when insufficient_privilege then null; end; end; $$;
create or replace function private.bingo_enabled() returns boolean language sql immutable set search_path='' as $$select true;$$;
do $$ begin begin perform private.bingo_mutation('complete','2026-10-05',0,'2026-10-05T00:00:59+02'); raise exception 'Before start accepted'; exception when insufficient_privilege then null; end; end; $$;
select pg_temp.check_bingo((private.bingo_mutation('complete','2026-10-05',0,'2026-10-05T00:01:00+02')->'score'->>'total_points')::integer=2,'Exact 00:01 start, first square scores two');
select pg_temp.check_bingo((private.bingo_mutation('complete','2026-10-05',1,'2026-10-05T12:00:00+02')->'score'->>'total_points')::integer=3,'Second square same day scores one');
select pg_temp.check_bingo((private.bingo_mutation('complete','2026-10-05',1,'2026-10-05T12:00:00+02')->'score'->>'total_points')::integer=3,'Repeat complete request is idempotent');
select pg_temp.check_bingo((private.bingo_mutation('uncomplete','2026-10-05',1,'2026-10-05T12:00:00+02')->'score'->>'total_points')::integer=2,'Uncheck recalculates points');
select pg_temp.check_bingo((private.bingo_mutation('repeat','2026-10-06',0,'2026-10-06T12:00:00+02')->'score'->>'total_points')::integer=2,'Repeat day grants no points');
select pg_temp.check_bingo(private.competition_day_complete('11111111-2222-4333-8444-555555555555','2026-10-06'),'Repeat maintains daily attendance');
do $$ begin begin perform private.bingo_mutation('complete','2026-10-07',2,'2026-10-06T12:00:00+02'); raise exception 'Future accepted'; exception when invalid_parameter_value then null; end; end; $$;
select pg_temp.check_bingo(private.find_missed_day_elimination('11111111-2222-4333-8444-555555555555','2026-10-07') is null,'One closed missed day remains active');
select pg_temp.check_bingo(private.find_missed_day_elimination('11111111-2222-4333-8444-555555555555','2026-10-08')='2026-10-08','Two consecutive closed missing bingo days eliminate');
select private.evaluate_user_elimination('11111111-2222-4333-8444-555555555555','2026-10-08');
do $$ begin begin perform private.bingo_mutation('complete','2026-10-09',2,'2026-10-09T12:00:00+02'); raise exception 'Eliminated current-day write accepted'; exception when insufficient_privilege then null; end; end; $$;
select pg_temp.check_bingo((private.bingo_mutation('complete','2026-10-07',2,'2026-10-09T12:00:00+02')->>'restored')::boolean,'Historical bingo correction restores automatic elimination');
select pg_temp.check_bingo((select competition_status='active' from public.profiles where id='11111111-2222-4333-8444-555555555555'),'Restored participant active');
select private.apply_elimination('11111111-2222-4333-8444-555555555555','Alkohol');
select private.bingo_mutation('complete','2026-10-08',3,'2026-10-09T12:00:00+02');
select pg_temp.check_bingo((select competition_status='eliminated' and elimination_reason='Alkohol' from public.profiles where id='11111111-2222-4333-8444-555555555555'),'Alcohol status survives historical correction');
select pg_temp.check_bingo((private.bingo_score((select jsonb_object_agg(i::text,'2026-10-05') from generate_series(0,24)i))->>'total_points')::integer=76,'Full board one day scores 76');
select pg_temp.check_bingo((private.bingo_score((select jsonb_object_agg(i::text,('2026-10-05'::date+i%7)::text) from generate_series(0,24)i))->>'total_points')::integer=82,'Full board seven days maximum 82');
select pg_temp.check_bingo((select sum(points)=82 from private.bingo_daily_scores((select jsonb_object_agg(i::text,('2026-10-05'::date+i%7)::text) from generate_series(0,24)i))),'Daily report allocations equal exact full board score');
select pg_temp.check_bingo((private.bingo_score('{"0":"2026-10-05","1":"2026-10-05","2":"2026-10-05","3":"2026-10-05","4":"2026-10-05"}')->>'line_points')::integer=3,'Completed horizontal row earns three');
select pg_temp.check_bingo((private.bingo_score('{"0":"2026-10-05","5":"2026-10-05","10":"2026-10-05","15":"2026-10-05","20":"2026-10-05"}')->>'line_points')::integer=3,'Completed vertical column earns three');
select pg_temp.check_bingo((select total_points=(private.bingo_score((select completed_cells from public.bingo_results where user_id='11111111-2222-4333-8444-555555555555'))->>'total_points')::numeric and completed_days=4 from public.get_leaderboard() where display_name='Bingo fixture one'),'Leaderboard adds bingo score and attendance');
select pg_temp.check_bingo(not has_function_privilege('authenticated','private.bingo_mutation(text,date,integer,timestamptz)','execute'),'Simulated clock helper is not client executable');
select pg_temp.check_bingo(not has_table_privilege('anon','public.bingo_results','select') and not has_table_privilege('authenticated','public.bingo_results','insert') and not has_table_privilege('authenticated','public.bingo_results','update'),'Anonymous raw data and direct writes denied');
select pg_temp.check_bingo((select bool_and(key=any(array['board_key','display_name','completed_cells','score','is_current_user','is_eliminated'])) from jsonb_array_elements(private.bingo_directory()->'participants')p cross join lateral jsonb_object_keys(p)key),'Directory exposes only intended fields');
select pg_temp.check_bingo(private.bingo_directory()::text not like '%11111111-2222-4333-8444-555555555555%' and private.bingo_directory()::text not like '%example.invalid%','Directory contains no account UUID or email');
select set_config('request.jwt.claims','{"sub":"11111111-2222-4333-8444-555555555556","role":"authenticated"}',true);
grant insert on bingo_qa_results to authenticated,anon;
set local role authenticated;
select pg_temp.check_bingo((select count(*)=1 from public.bingo_results),'RLS reads only own board');
reset role;
select set_config('request.jwt.claims','{}',true);
do $$ begin begin insert into public.daily_results(user_id,result_date,multiplier) values('11111111-2222-4333-8444-555555555556','2026-10-05',1); raise exception 'Hidden workout accepted'; exception when insufficient_privilege then null; end; end; $$;
select pg_temp.check_bingo(private.find_missed_day_elimination('11111111-2222-4333-8444-555555555556','2026-09-30') is null,'No false misses before October');
select pg_temp.check_bingo(not private.bingo_cells_valid('{"25":"2026-10-05"}') and not private.bingo_cells_valid('{"0":"2026-10-12"}'),'Invalid cell and period dates rejected');
select pg_temp.check_bingo((select checksum=(select md5(coalesce(jsonb_agg(to_jsonb(s) order by to_jsonb(s)::text)::text,'')) from public.bingo_test_sessions s) from baseline_sandbox),'Admin sandbox progress left unchanged');
select pg_temp.check_bingo(private.find_missed_day_elimination('11111111-2222-4333-8444-555555555556','2026-10-05')='2026-10-05','Missing Oct 4 workout and Oct 5 bingo count across start boundary');
update public.profiles set auto_elimination_recheck_after='2026-10-10' where id='11111111-2222-4333-8444-555555555556';
select set_config('request.jwt.claims','{"sub":"11111111-2222-4333-8444-555555555556","role":"authenticated"}',true);
select private.bingo_mutation('complete','2026-10-10',0,'2026-10-10T12:00:00+02');
select pg_temp.check_bingo(private.find_missed_day_elimination('11111111-2222-4333-8444-555555555556','2026-10-12')='2026-10-12','Missing Oct 11 bingo and Oct 12 workout count across end boundary');
select set_config('request.jwt.claims','{"sub":"11111111-2222-4333-8444-555555555556","role":"authenticated"}',true);
insert into public.step_period_results(user_id,period_key,avg_steps) values('11111111-2222-4333-8444-555555555556','oct_01_07',10000);
select pg_temp.check_bingo((select avg_steps=10000 from public.step_period_results where user_id='11111111-2222-4333-8444-555555555556'),'Step writes unaffected by daily bingo guard');
set local role anon;
select pg_temp.check_bingo(jsonb_array_length(public.get_bingo_directory()->'board')=25,'Public directory works for anonymous visitors');
reset role;
select jsonb_agg(test) tests_passed from bingo_qa_results;
